// STUB — replace this node with your four real email input branches
// (IMAP / Gmail / Microsoft Outlook / NextCloud). Each real branch should
// output items shaped like the objects below: {account, priority, from,
// subject, snippet, date, headers}. GiveSendGo Charities is priority 1.
const now = new Date().toISOString();
return [
  { json: { account: 'givesendgo', priority: 1, from: 'donor@example.org', subject: 'Recurring gift failed to process', snippet: 'Our monthly gift did not go through this month — can you help sort it out today?', date: now, headers: {} } },
  { json: { account: 'gmail', priority: 2, from: 'jane@partner.com', subject: 'Contract redline ready for review', snippet: 'Sending the redlined MSA back for your review before Friday.', date: now, headers: {} } },
  { json: { account: 'outlook', priority: 2, from: 'no-reply@newsletter.com', subject: 'Your weekly digest', snippet: 'Top stories this week and a few picks for you...', date: now, headers: { 'list-unsubscribe': '<https://unsub.example>' } } },
  { json: { account: 'nextcloud', priority: 2, from: 'ops@vendor.io', subject: 'Invoice #4821 now overdue', snippet: 'A friendly reminder that invoice 4821 is 14 days overdue.', date: now, headers: {} } }
];

// Free pre-filter — runs BEFORE any Claude call to keep cost down.
// 1) drop mail older than 24h, 2) drop newsletters/bulk, 3) trim each item.
const CUTOFF = Date.now() - 24 * 60 * 60 * 1000;
const out = [];
for (const item of $input.all()) {
  const e = item.json;
  const from = (e.from || '').toString();
  const subject = (e.subject || '').toString();
  const body = (e.snippet || e.text || e.textPlain || '').toString();
  const ts = e.date ? new Date(e.date).getTime() : Date.now();
  if (ts && ts < CUTOFF) continue;
  const headers = JSON.stringify(e.headers || {}).toLowerCase();
  const isBulk = headers.includes('list-unsubscribe') || /no-?reply|newsletter|notifications?@/i.test(from);
  if (isBulk) continue;
  out.push({ json: {
    account: e.account || 'other',
    priority: e.priority || 2,
    from,
    subject,
    snippet: body.replace(/\s+/g, ' ').trim().slice(0, 600),
    date: e.date || null
  } });
}
return out;

// Pair each Haiku response back with its email (index-aligned), parse the
// classification, and drop anything triaged as 'ignore'.
const emails = $('Free Pre-Filter').all();
const all = $input.all();
const out = [];
for (let i = 0; i < all.length; i++) {
  const email = emails[i] ? emails[i].json : {};
  let text = '';
  try { text = all[i].json.content[0].text; } catch (e) {}
  let parsed = { classification: 'fyi', one_line: email.subject || '' };
  try { parsed = JSON.parse(text); } catch (e) {}
  if (parsed.classification === 'ignore') continue;
  out.push({ json: { ...email, classification: parsed.classification || 'fyi', one_line: parsed.one_line || email.subject || '' } });
}
return out;

// Group triaged items by account (GiveSendGo first) and build ONE prompt
// for the single Sonnet synthesis pass.
const items = $input.all().map(i => i.json);
const order = { givesendgo: 1, gmail: 2, outlook: 3, nextcloud: 4 };
items.sort((a, b) => (a.priority - b.priority) || ((order[a.account] || 9) - (order[b.account] || 9)));
const byAccount = {};
for (const it of items) { (byAccount[it.account] = byAccount[it.account] || []).push(it); }
const accounts = Object.keys(byAccount).sort((a, b) => (order[a] || 9) - (order[b] || 9));
let input = '';
for (const acc of accounts) {
  input += '\n## ' + acc + '\n';
  for (const it of byAccount[acc]) {
    input += '- [' + it.classification + '] ' + it.from + ' \u2014 ' + it.subject + ' :: ' + (it.one_line || '') + '\n';
  }
}
const synthSystem = 'You are a Chief of Staff writing one concise daily morning brief. Group strictly by account in the order given. GiveSendGo Charities MUST appear first. Within each account, list needs_reply items before fyi. Be terse and scannable, markdown headers, no invented items.';
const synthUser = 'Write the morning brief from these triaged items, grouped by account (GiveSendGo first):\n' + input;
return [{ json: { synthSystem, synthUser } }];

// Pull the brief text out of the Sonnet response.
let text = '';
try { text = $input.first().json.content[0].text; } catch (e) { text = '(no brief generated)'; }
return [{ json: { brief: text } }];
